174	
175	  const addEvent = async (payload: CreateLabelEventPayload) => {
176	    if (!fightId) return null;
177	    setSavingCount(c => c + 1);
178	    try {
179	      const created = await createLabelEvent(fightId, payload);
180	      setEvents(prev => [...prev, created]);
181	      sessionIdsRef.current.push(created.id);
182	      flash(created.id);
183	      return created;
184	    } catch {
185	      showToast('Failed to save event', 'var(--f-red)', 'error');
186	      return null;
187	    } finally {
188	      setSavingCount(c => c - 1);
189	    }
190	  };
191	
192	  const removeEvent = async (eventId: number) => {
193	    if (!fightId) return;
194	    setSavingCount(c => c + 1);
195	    try {
196	      await deleteLabelEvent(fightId, eventId);
197	      setEvents(prev => prev.filter(e => e.id !== eventId));
198	      sessionIdsRef.current = sessionIdsRef.current.filter(x => x !== eventId);
199	      if (selectedEventIdRef.current === eventId) setSelectedEventId(null);
200	    } catch {
201	      showToast('Failed to delete event', 'var(--f-red)', 'error');
202	    } finally {
203	      setSavingCount(c => c - 1);
204	    }
205	  };
206	
207	  // corner_swap / excluded are start/end toggles: one key opens a span at the
208	  // playhead, the next press of the same key closes it. `openSpanRef` tracks
209	  // the in-flight span id per kind so the second press knows what to close.
210	  const openSpanRef = useRef<Partial<Record<SpanKind, number>>>({});
211	  const SPAN_LABEL: Record<SpanKind, string> = { round: 'Round', corner_swap: 'Corner swap', excluded: 'Excluded' };
212	
213	  const toggleSpan = async (kind: SpanKind) => {
214	    if (!fightId) return;
215	    const openId = openSpanRef.current[kind];
216	    const frame = frameRef.current;
217	    if (openId != null) {
218	      try {
219	        const start = spans.find(s => s.id === openId)?.start_frame ?? frame;
220	        const patch = frame < start ? { start_frame: frame, end_frame: start } : { end_frame: frame };
221	        const updated = await updateLabelSpan(fightId, openId, patch);
222	        setSpans(prev => prev.map(s => (s.id === openId ? updated : s)));
223	        showToast(`${SPAN_LABEL[kind]} span closed`, 'var(--slate-400)', 'flag');
224	      } catch {
225	        showToast('Failed to close span', 'var(--f-red)', 'error');
226	      } finally {
227	        delete openSpanRef.current[kind];
228	      }
229	      return;
230	    }
231	    try {
232	      const created = await createLabelSpan(fightId, {
233	        kind, start_frame: frame, value: kind === 'excluded' ? 'replay' : null,
234	      });
235	      setSpans(prev => [...prev, created]);
236	      openSpanRef.current[kind] = created.id;
237	      showToast(`${SPAN_LABEL[kind]} span opened`, 'var(--slate-400)', 'flag');
238	    } catch {
239	      showToast('Failed to open span', 'var(--f-red)', 'error');
240	    }
241	  };
242	
243	  const updateSpan = async (spanId: number, patch: { start_frame?: number; end_frame?: number }) => {
244	    if (!fightId) return;
245	    try {
246	      const updated = await updateLabelSpan(fightId, spanId, patch);
247	      setSpans(prev => prev.map(s => (s.id === spanId ? updated : s)));
248	    } catch {
249	      showToast('Failed to update span', 'var(--f-red)', 'error');
250	    }
251	  };
252	
253	  const removeSpan = async (spanId: number) => {
254	    if (!fightId) return;
255	    try {
256	      await deleteLabelSpan(fightId, spanId);
257	      setSpans(prev => prev.filter(s => s.id !== spanId));
258	      for (const [kind, id] of Object.entries(openSpanRef.current)) {
259	        if (id === spanId) delete openSpanRef.current[kind as SpanKind];
260	      }
261	    } catch {
262	      showToast('Failed to delete span', 'var(--f-red)', 'error');
263	    }
264	  };
265	
266	  const undo = () => {
267	    const lastId = sessionIdsRef.current[sessionIdsRef.current.length - 1];
268	    if (lastId == null) return;
269	    removeEvent(lastId);
270	  };
271	
272	  const logTool = (item: ToolItem, shiftKey = false) => {
273	    if (!selectedFight) return;
274	    const corner = selRef.current;
275	    if (item.needsFighter && !corner) {
276	      setHint(true);
277	      clearTimeout(hintTimer.current);
278	      hintTimer.current = setTimeout(() => setHint(false), 1100);
279	      showToast('Select a fighter first', 'var(--f-red)', 'error');
280	      return;
281	    }
282	    // Fighter-independent tools (fight state) must not pick up whichever corner
283	    // happens to be selected — neither in the stored corner nor in the toast.
284	    const cornerIdx = item.needsFighter ? (corner === 'red' ? 0 : 1) : null;
285	    const fighterName = item.needsFighter ? (corner === 'red' ? redName : blueName) : '';
286	    const target = item.hasTarget ? (shiftKey ? 'body' : 'head') : item.fixedTarget ?? null;
287	    const description = item.text(fighterName, target ?? undefined);
288	    const color = colorForAction(item.action);
289	    const icon = iconForAction(item.action);
290	    addEvent({
291	      frame: frameRef.current,
292	      description,
293	      corner: cornerIdx,
294	      action: item.action,
295	      target,
296	      success: successForAction(item.action),
297	    }).then(created => {
298	      if (!created) return;
299	      if (!item.needsFighter) { showToast(description, color, icon); return; }
300	      const targetSuffix = item.hasTarget ? ` · ${target === 'body' ? 'Body' : 'Head'}` : '';
301	      showToast(`${item.name} · ${fighterName}${targetSuffix}`, color, icon);
302	    });
303	  };
304	
305	  const confirmFightEnd = (result: FightEndResult) => {
306	    const winnerCorner = result.winner === 'red' ? 0 : result.winner === 'blue' ? 1 : null;
307	    const winnerName = result.winner === 'red' ? redName : result.winner === 'blue' ? blueName : null;
308	    const outcome = result.method === 'Draw' || !winnerName
309	      ? 'Draw'
310	      : result.method === 'Decision' ? `${winnerName} by decision` : `${winnerName} by ${result.method}`;
311	    const description = `Fight ended — ${outcome}${result.detail ? ' (' + result.detail + ')' : ''}`;
312	    const endFrame = frameRef.current;
313	    addEvent({
314	      frame: endFrame,
315	      description,
316	      corner: winnerCorner,
317	      action: 'fight_end',
318	      success: null,
319	    }).then(created => {
320	      if (!created) return;
321	      showToast(`Fight ended · ${result.method}`, 'var(--purple-600)', 'sports_score');
322	
323	      // The round span was seeded from the AI's scheduled-length guess,
324	      // which now runs past the real end of the fight — auto-exclude the
325	      // tail so it isn't scored/trained on as if it were live action.
326	      // Visible and editable in the timeline like any other excluded span,
327	      // not a silent adjustment (TODO.md #4).
328	      if (!fightId) return;
329	      const containingRound = spans.find(
330	        s => s.kind === 'round' && s.start_frame <= endFrame &&
331	             (s.end_frame == null || endFrame <= s.end_frame),
332	      );
333	      if (containingRound?.end_frame != null && containingRound.end_frame > endFrame) {
334	        createLabelSpan(fightId, {
335	          kind: 'excluded',
336	          start_frame: endFrame + 1,
337	          end_frame: containingRound.end_frame,
338	          value: 'post fight_end',
339	        }).then(span => setSpans(prev => [...prev, span]));
340	      }
341	    });
342	    setEndOpen(false);
343	  };
344	
345	  const handleFinishLabeling = async () => {
346	    if (!fightId) return;
347	    setFinishing(true);
348	    try {
349	      await finishLabeling(fightId);
350	      navigate(`/fights/${fightId}`);
351	    } catch (err) {
352	      showToast(err instanceof Error ? err.message : 'Failed to finish labeling', 'var(--f-red)', 'error');
353	      setFinishing(false);
354	    }
355	  };
356	
357	  const handleDeleteFight = async () => {
358	    if (!fightId) return;
359	    setDeletingFight(true);
360	    setDeleteError(null);
361	    try {
362	      // The DELETE unlinks the file this <video> is streaming — stop playback
363	      // (and the requestVideoFrameCallback loop) before pulling it out from under us.
364	      videoRef.current?.pause();
365	      setIsPlaying(false);
366	      await deleteFight(fightId);
367	      // replace: Back must not return to a now-dead /fights/{id}/annotate.
368	      navigate('/', { replace: true });
369	    } catch (err) {
370	      setDeleteError(err instanceof Error ? err.message : 'Failed to delete fight');
371	      setDeletingFight(false);
372	    }
373	  };
374	
375	  // stable "latest callback" ref so the global keydown listener (registered once)
376	  // always calls the current render's closures, without re-registering constantly
377	  const fnsRef = useRef({ togglePlay, stepFrame, logTool, undo, setSelected, toggleSpan, removeEvent });
378	  fnsRef.current = { togglePlay, stepFrame, logTool, undo, setSelected, toggleSpan, removeEvent };
379	
380	  useEffect(() => {
381	    if (!ready) return;
382	    const onKey = (e: KeyboardEvent) => {
383	      if (e.metaKey || e.ctrlKey || e.altKey) return;
384	      const target = e.target as HTMLElement;
385	      const tag = target.tagName;
386	      if (tag === 'INPUT' || tag === 'TEXTAREA' || target.isContentEditable) return;
387	      // Any modal swallows every shortcut — otherwise z/o/p/digits keep logging
388	      // label events behind the overlay, and Escape would double-fire.
389	      if (endOpenRef.current || confirmDeleteRef.current) return;
390	
391	      const fns = fnsRef.current;
392	      const k = e.key;
393	      const time = (frameRef.current - 1) / fpsRef.current;
394	
395	      if (k === ' ') { e.preventDefault(); fns.togglePlay(); return; }
396	      if (k === 'ArrowLeft') { e.preventDefault(); handleSeek(Math.max(0, time - (e.shiftKey ? 5 : 1))); return; }
397	      if (k === 'ArrowRight') { e.preventDefault(); handleSeek(time + (e.shiftKey ? 5 : 1)); return; }
398	      if (k === ',') { e.preventDefault(); fns.stepFrame(-1); return; }
399	      if (k === '.') { e.preventDefault(); fns.stepFrame(1); return; }
400	      if (k === 'Escape') { fns.setSelected(null); setSelectedEventId(null); return; }
401	
402	      const lk = k.length === 1 ? k.toLowerCase() : k;
403	      if (lk === 'r') { fns.setSelected('red'); return; }
404	      if (lk === 'b') { fns.setSelected('blue'); return; }
405	      // Backspace/Delete: delete the selected timeline clip if one is
406	      // selected, else undo the last event logged this session. On Mac the
407	      // one physical "delete" key sends Backspace (e.key === 'Delete' is
408	      // only the separate forward-delete, Fn+Delete) — so this has to be
409	      // one binding that branches on selection, not two separate keys.
410	      if (k === 'Backspace' || k === 'Delete') {
411	        e.preventDefault();
412	        if (selectedEventIdRef.current != null) fns.removeEvent(selectedEventIdRef.current);
413	        else fns.undo();
414	        return;
415	      }
416	      if (lk === 'z') { e.preventDefault(); fns.undo(); return; }
417	      if (lk === 'o') { e.preventDefault(); fns.toggleSpan('corner_swap'); return; }
418	      if (lk === 'p') { e.preventDefault(); fns.toggleSpan('excluded'); return; }
419	
420	      // Digit keys need e.code, not e.key: Shift+1 types '!' on a US layout,
421	      // so reading e.key would break the KEYMAP lookup for the target modifier.
422	      const toolKey = e.code.startsWith('Digit') ? e.code.slice(5) : lk;
423	      const tool = KEYMAP[toolKey];
424	      if (tool) { e.preventDefault(); fns.logTool(tool, e.shiftKey); }
425	    };
426	    window.addEventListener('keydown', onKey);
427	    return () => window.removeEventListener('keydown', onKey);
428	  }, [ready]);
429	
430	  // ---- guard states ----
431	  if (selectedFight === null) {
432	    return (
433	      <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', minHeight: 'calc(100vh - 58px)', padding: 24 }}>
434	        <span className="material-symbols-outlined" style={{ fontSize: 32, color: '#64748b', animation: 'spin 1.5s linear infinite' }}>progress_activity</span>
435	      </div>
436	    );
437	  }
438	
439	  if (isFightViewable(selectedFight.state)) {
440	    return (
441	      <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', minHeight: 'calc(100vh - 58px)', padding: 24 }}>
442	        <div style={{
443	          textAlign: 'center', background: 'rgba(255,255,255,0.04)', backdropFilter: 'blur(24px) saturate(160%)',
444	          border: '1px solid rgba(255,255,255,0.07)', borderRadius: 20, padding: '48px 56px', maxWidth: 420,
445	        }}>
446	          <span className="material-symbols-outlined" style={{ fontSize: 40, color: 'var(--accent)', display: 'block', marginBottom: 16 }}>check_circle</span>
447	          <h2 style={{ fontSize: 20, fontWeight: 800, margin: '0 0 10px', color: '#f1f5f9' }}>This fight is already labeled</h2>
448	          <p style={{ fontSize: 14, color: '#475569', margin: '0 0 20px', lineHeight: 1.6 }}>Open it in the Player to review the tagged events.</p>
449	          <button onClick={() => navigate(`/fights/${selectedFight.id}`)} className="btn-glass" style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '8px 16px', fontSize: 13, fontWeight: 600, borderRadius: 8 }}>
450	            <span className="material-symbols-outlined" style={{ fontSize: 16 }}>play_circle</span>
451	            Open Player
452	          </button>
453	        </div>
454	      </div>
455	    );
456	  }
457	
458	  if (!ready) {
459	    return (
460	      <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', minHeight: 'calc(100vh - 58px)', padding: 24 }}>
461	        <div style={{
462	          textAlign: 'center', background: 'rgba(255,255,255,0.04)', backdropFilter: 'blur(24px) saturate(160%)',
463	          border: '1px solid rgba(255,255,255,0.07)', borderRadius: 20, padding: '48px 56px', maxWidth: 420,
464	        }}>
465	          <span className="material-symbols-outlined" style={{ fontSize: 40, color: '#64748b', display: 'block', marginBottom: 16, animation: 'spin 1.5s linear infinite' }}>progress_activity</span>
466	          <h2 style={{ fontSize: 20, fontWeight: 800, margin: '0 0 10px', color: '#f1f5f9' }}>
467	            {STATE_LABELS[selectedFight.state] ?? 'Detecting fighters'}
468	          </h2>
469	          <p style={{ fontSize: 14, color: '#475569', margin: '0 0 20px', lineHeight: 1.6 }}>
470	            Fighters are still being detected — labeling opens once that's done.
471	          </p>
472	          <button onClick={() => navigate('/')} className="btn-glass" style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '8px 16px', fontSize: 13, fontWeight: 600, borderRadius: 8 }}>
473	            <span className="material-symbols-outlined" style={{ fontSize: 16 }}>arrow_back</span>
474	            Back to fights
475	          </button>
476	        </div>
477	      </div>
478	    );
479	  }
480	
481	  return (
482	    <div style={{ position: 'relative', zIndex: 1, width: '100%', boxSizing: 'border-box', maxWidth: 1560, margin: '0 auto', padding: narrow ? '16px 14px 48px' : '22px 30px 70px' }}>
483	      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16 }}>
484	        <button onClick={() => navigate('/')} className="icon-btn" style={{ width: 38, height: 38 }}>
485	          <span className="material-symbols-outlined" style={{ fontSize: 20 }}>arrow_back</span>
486	        </button>
487	        <div>
488	          <div className="font-display" style={{ fontSize: 30, letterSpacing: '0.03em', color: '#f1f5f9', lineHeight: 1 }}>SELF-ANNOTATE</div>
489	          <div style={{ fontSize: 12.5, color: '#64748b', fontWeight: 600, marginTop: 3 }}>{redName} vs {blueName}</div>
490	        </div>
491	        <FightPurposeBadge purpose={selectedFight.purpose} />
492	        <span style={{ flex: 1 }} />
493	        <SaveStatus saving={savingCount > 0} />
494	        <button
495	          onClick={handleFinishLabeling}
496	          disabled={finishing}
497	          style={{
498	            display: 'inline-flex', alignItems: 'center', gap: 8, background: 'linear-gradient(135deg, #00daf3, #0099b0)',
499	            color: '#001f24', fontWeight: 700, fontSize: 13, border: 'none', borderRadius: 10, padding: '9px 16px',
500	            cursor: finishing ? 'not-allowed' : 'pointer', opacity: finishing ? 0.5 : 1,
501	            boxShadow: finishing ? 'none' : '0 0 16px rgba(0,218,243,0.25)', fontFamily: 'inherit',
502	          }}
503	        >
504	          <span className="material-symbols-outlined" style={{ fontSize: 18 }}>{finishing ? 'progress_activity' : 'task_alt'}</span>
505	          Finish Labeling
506	        </button>
507	        <button
508	          onClick={() => { setDeleteError(null); setConfirmDelete(true); }}
509	          title="Delete this fight"
510	          style={{
511	            width: 38, height: 38, flexShrink: 0, display: 'grid', placeItems: 'center',
512	            borderRadius: 10, border: '1px solid rgba(239,68,68,0.25)',
513	            background: 'rgba(239,68,68,0.08)', color: '#ef4444',
514	            cursor: 'pointer', fontFamily: 'inherit',
515	          }}
516	        >
517	          <span className="material-symbols-outlined" style={{ fontSize: 20 }}>delete</span>
518	        </button>
519	      </div>
520	
521	      <ConfirmDialog
522	        open={confirmDelete}
523	        title="DELETE FIGHT?"
524	        message={
525	          <>
526	            <strong style={{ color: 'var(--text-primary)' }}>{redName} vs {blueName}</strong> will be
527	            permanently deleted — the source video file, every hand label and span you have annotated
528	            so far, plus all pipeline predictions, rounds and tracked fighter frames. This cannot be undone.
529	          </>
530	        }
531	        confirmLabel="Delete fight"
532	        confirmIcon="delete_forever"
533	        danger
534	        busy={deletingFight}
535	        error={deleteError}
536	        onCancel={() => setConfirmDelete(false)}
537	        onConfirm={handleDeleteFight}
538	      />
539	
540	      {needsRoundReview(selectedFight) && (
541	        <div style={{
542	          display: 'flex',
543	          alignItems: 'flex-start',
544	          gap: 10,
545	          marginBottom: 14,
546	          padding: '11px 14px',
547	          borderRadius: 10,
548	          border: '1px solid rgba(245,158,11,0.25)',
549	          background: 'rgba(245,158,11,0.07)',
550	        }}>
551	          <span className="material-symbols-outlined" style={{ fontSize: 19, color: '#f59e0b', flexShrink: 0 }}>
552	            rule
553	          </span>
554	          <div style={{ minWidth: 0 }}>
555	            <div style={{ fontSize: 13, fontWeight: 700, color: '#f59e0b', marginBottom: 2 }}>
556	              Round boundaries are unverified
557	            </div>
558	            <div style={{ fontSize: 12, color: 'rgba(255,255,255,0.55)', lineHeight: 1.5 }}>
559	              {selectedFight.segmentation_review_reason
560	                ?? 'Segmentation could not confirm these rounds against the scoreboard.'}
561	              {' '}Check the ROUNDS lane below and drag the edges before labelling.
562	            </div>
563	          </div>
564	        </div>
565	      )}
566	
567	      <div style={{ display: 'grid', gridTemplateColumns: narrow ? '1fr' : '1fr 460px', gap: 16, alignItems: 'stretch' }}>
568	        <div style={{ display: 'flex', flexDirection: 'column' }}>
569	          <AnnotateStage
570	            videoRef={videoRef}
571	            overlayRef={overlayRef}
572	            src={videoSrc}
573	            isPlaying={isPlaying}
