575	            onLoadedMetadata={() => { const v = videoRef.current; if (v) setDuration(v.duration); }}
576	            onPlay={() => setIsPlaying(true)}
577	            onPause={() => setIsPlaying(false)}
578	            onTogglePlay={togglePlay}
579	            onStepForward={() => stepFrame(1)}
580	            onStepBackward={() => stepFrame(-1)}
581	            frameMap={frameMap}
582	            fightWidth={selectedFight.width}
583	            fightHeight={selectedFight.height}
584	            currentRound={currentRound}
585	            selectedCorner={selected}
586	            redName={redName}
587	            blueName={blueName}
588	            toast={toast}
589	          />
590	
591	          <VideoControls
592	            isPlaying={isPlaying}
593	            currentTime={currentTime}
594	            duration={duration}
595	            onTogglePlay={togglePlay}
596	            onSeek={handleSeek}
597	            onStepBackward={() => stepFrame(-1)}
598	            onStepForward={() => stepFrame(1)}
599	          />
600	
601	          <FrameInfo currentFrame={currentFrame} currentMs={currentMs} fps={fps} />
602	
603	          <KeyboardLegend />
604	        </div>
605	
606	        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
607	          <div className="glass" style={{ padding: '18px 18px 20px', borderRadius: 14 }}>
608	            <div className="label" style={{ fontSize: 9.5, marginBottom: 11 }}>Active fighter</div>
609	            <FighterSelectCard
610	              selected={selected}
611	              onSelect={c => setSelected(s => (s === c ? null : c))}
612	              redName={redName}
613	              blueName={blueName}
614	              hint={hint}
615	            />
616	            <hr className="divider" style={{ margin: '18px 0 16px' }} />
617	            <EventPalette selected={selected !== null} onLog={logTool} onFightEnd={() => setEndOpen(true)} />
618	          </div>
619	        </div>
620	      </div>
621	
622	      <AnnotationPanel
623	        events={events}
624	        spans={spans}
625	        rounds={rounds}
626	        duration={duration}
627	        fps={fps}
628	        currentFrame={currentFrame}
629	        onSeek={seekToFrame}
630	        onSetPlaying={setIsPlaying}
631	        onDelete={removeEvent}
632	        onUpdateSpan={updateSpan}
633	        onDeleteSpan={removeSpan}
634	        flashId={flashId}
635	        selectedEventId={selectedEventId}
636	        onSelectEvent={setSelectedEventId}
637	        redName={redName}
638	        blueName={blueName}
639	      />
640	
641	      {endOpen && (
642	        <FightEndModal
643	          currentRound={currentRound}
644	          timeLabel={`${Math.floor(currentTime / 60)}:${String(Math.floor(currentTime % 60)).padStart(2, '0')}`}
645	          redName={redName}
646	          blueName={blueName}
647	          onClose={() => setEndOpen(false)}
648	          onConfirm={confirmFightEnd}
649	        />
650	      )}
651	    </div>
652	  );
653	}
