1	/**
2	 * Single source of truth for the manual-annotation palette: each ToolItem
3	 * drives the palette button, its keyboard shortcut, and the keyboard legend
4	 * simultaneously. Round boundaries aren't here — real Round rows already
5	 * exist from AI segmentation (see ai/fight_processing/write_frames_and_rounds).
6	 * Only "fight end" stays manual since no stage detects a fight's conclusion.
7	 */
8	
9	export type Corner = 'red' | 'blue';
10	export type EventCat = 'strike' | 'grapple' | 'state' | 'round' | 'event';
11	export type Target = 'head' | 'body' | 'leg';
12	
13	export interface ToolItem {
14	  key: string;
15	  num?: string;
16	  action: string;
17	  name: string;
18	  text: (fighterName: string, target?: Target) => string;
19	  needsFighter: boolean;
20	  /** Shift-modified: plain key = head, Shift+key = body. Read via e.code + e.shiftKey. */
21	  hasTarget?: boolean;
22	  /** Kicks already encode target in the action name — no modifier needed. */
23	  fixedTarget?: Target;
24	}
25	
26	export interface ToolGroup {
27	  group: string;
28	  note?: string;
29	  items: ToolItem[];
30	}
31	
32	// Shared by every hand strike + elbow so the description always reflects the
33	// real target instead of a value baked in per-action (right_hook used to be
34	// hardcoded "to the body" regardless of where it actually landed).
35	//
36	// jab/cross are lead/rear-relative (boxing terms), not absolute-handed —
37	// a southpaw's jab is thrown with their right hand. Hooks/uppercuts stay
38	// absolute left/right: that's what you can directly see (which arm moved)
39	// without first judging stance, and it's lossless either way since both
40	// hands collapse to the same family (`hook`/`uppercut`) at export time.
41	const HAND_STRIKE_NAMES: Record<string, string> = {
42	  jab: 'jab',
43	  cross: 'cross',
44	  left_hook: 'left hook',
45	  right_hook: 'right hook',
46	  left_uppercut: 'left uppercut',
47	  right_uppercut: 'right uppercut',
48	  elbow: 'elbow',
49	};
50	
51	function handStrikeText(action: string, fighterName: string, target: Target = 'head'): string {
52	  return `${fighterName} ${HAND_STRIKE_NAMES[action]} to the ${target}`;
53	}
54	
55	export const TOOL_GROUPS: ToolGroup[] = [
56	  {
57	    group: 'Strikes',
58	    note: 'Jab/cross = lead/rear hand (works for southpaws) · hooks/uppercuts = literal left/right · Shift = body',
59	    items: [
60	      { key: '1', num: '1', action: 'jab', name: 'Jab', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('jab', f, t) },
61	      { key: '2', num: '2', action: 'cross', name: 'Cross', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('cross', f, t) },
62	      { key: '3', num: '3', action: 'left_hook', name: 'Left hook', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('left_hook', f, t) },
63	      { key: '4', num: '4', action: 'right_hook', name: 'Right hook', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('right_hook', f, t) },
64	      { key: '5', num: '5', action: 'left_uppercut', name: 'Left uppercut', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('left_uppercut', f, t) },
65	      { key: '6', num: '6', action: 'right_uppercut', name: 'Right uppercut', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('right_uppercut', f, t) },
66	      { key: 'c', action: 'calf_kick', name: 'Calf kick', needsFighter: true, fixedTarget: 'leg', text: f => `${f} calf kick` },
67	      { key: 'l', action: 'low_kick', name: 'Low kick', needsFighter: true, fixedTarget: 'leg', text: f => `${f} low kick` },
68	      { key: 'm', action: 'middle_kick', name: 'Middle kick', needsFighter: true, fixedTarget: 'body', text: f => `${f} middle kick to the body` },
69	      { key: 'h', action: 'high_kick', name: 'High kick', needsFighter: true, fixedTarget: 'head', text: f => `${f} high kick to the head` },
70	      { key: 'e', action: 'elbow', name: 'Elbow', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('elbow', f, t) },
71	      { key: 'n', action: 'clinch_knee', name: 'Clinch knee', needsFighter: true, text: f => `${f} knee in the clinch` },
72	    ],
73	  },
74	  {
75	    group: 'Ground & pound',
76	    note: 'No target/hand breakdown — same reason MMA stats don’t: a scramble isn’t a clean jab/hook, so this is punch/knee volume only',
77	    items: [
78	      { key: 'u', action: 'clinch_punch', name: 'Clinch punch', needsFighter: true, text: f => `${f} punches in the clinch` },
79	      { key: 'v', action: 'ground_punch', name: 'Ground and pound', needsFighter: true, text: f => `${f} lands ground and pound` },
80	      { key: 'j', action: 'ground_knee', name: 'Ground knee', needsFighter: true, text: f => `${f} knees from the ground` },
81	    ],
82	  },
83	  {
84	    group: 'Grappling',
85	    items: [
86	      { key: 't', action: 'takedown_attempt', name: 'Takedown attempt', needsFighter: true, text: f => `${f} shoots for a takedown` },
87	      { key: 'y', action: 'takedown_landed', name: 'Takedown landed', needsFighter: true, text: f => `${f} lands a takedown` },
88	      { key: 'd', action: 'takedown_defended', name: 'Takedown defended', needsFighter: true, text: f => `${f} defends the takedown` },
89	      { key: 's', action: 'submission_attempt', name: 'Submission', needsFighter: true, text: f => `${f} threatens a submission` },
90	    ],
91	  },
92	  {
93	    group: 'Outcome',
94	    items: [
95	      { key: 'x', action: 'knockdown', name: 'Knockdown', needsFighter: true, text: f => `${f} scores a KNOCKDOWN` },
96	    ],
97	  },
98	  {
99	    group: 'Fight state',
100	    items: [
101	      { key: 'w', action: 'state_striking', name: 'Striking', needsFighter: false, text: () => 'Fight state → STRIKING' },
102	      { key: 'f', action: 'state_clinch', name: 'Clinch', needsFighter: false, text: () => 'Fight state → CLINCH' },
103	      { key: 'g', action: 'state_ground', name: 'Ground', needsFighter: false, text: () => 'Fight state → GROUND' },
104	    ],
105	  },
106	];
107	
108	export const KEYMAP: Record<string, ToolItem> = {};
109	TOOL_GROUPS.forEach(g => g.items.forEach(it => { KEYMAP[it.key] = it; }));
110	
111	// Landed-vs-missed is deferred (MVP target is "count strikes thrown"), so every
112	// strike logs success=null — outcome unknown, not a claim that it landed.
113	// `knockdown` and `takedown_landed` are the exceptions: neither is a default
114	// outcome of pressing the key (unlike a strike, which the palette has no
115	// landed/missed toggle for), so a logged one genuinely happened.
116	const SUCCESS_TRUE_ACTIONS = new Set(['knockdown', 'takedown_landed']);
117	
118	export function successForAction(action: string): boolean | null {
119	  return SUCCESS_TRUE_ACTIONS.has(action) ? true : null;
120	}
121	
122	export function categoryForAction(action: string | null): EventCat {
123	  if (!action) return 'state';
124	  if (action === 'fight_end' || action === 'submission_attempt') return 'event';
125	  if (action.startsWith('takedown_')) return 'grapple';
126	  if (action.startsWith('state_')) return 'state';
