2	import type { Event } from '../../types/Event';
3	import { deriveEventCat, eventColor, eventIcon } from './eventMeta';
4	
5	interface LiveFeedProps {
6	  events: Event[];
7	  currentFrame: number;
8	  fps: number;
9	  onSeek: (time: number) => void;
10	}
11	
12	type Filter = 'all' | 'strike' | 'state' | 'grapple';
13	
14	const FILTERS: { key: Filter; label: string }[] = [
15	  { key: 'all',    label: 'All' },
16	  { key: 'strike', label: 'Strikes' },
17	  { key: 'state',  label: 'Fight State' },
18	  { key: 'grapple',label: 'Grapple' },
19	];
20	
21	function matchFilter(cat: string, filter: Filter): boolean {
22	  if (filter === 'all') return true;
23	  if (filter === 'grapple') return cat === 'grapple' || cat === 'event';
24	  if (filter === 'state') return cat === 'state' || cat === 'round';
25	  return cat === filter;
26	}
27	
28	function fmtFrame(frame: number, fps: number): string {
29	  const secs = Math.max(0, Math.floor((frame - 1) / fps));
30	  const m = Math.floor(secs / 60);
31	  const s = secs % 60;
32	  return `${m}:${String(s).padStart(2, '0')}`;
33	}
34	
35	export default function LiveFeed({ events, currentFrame, fps, onSeek }: LiveFeedProps) {
36	  const [filter, setFilter] = useState<Filter>('all');
37	  const scrollRef = useRef<HTMLDivElement>(null);
38	
39	  const enriched = useMemo(() => events.map(e => ({
40	    ...e,
41	    cat: deriveEventCat(e.description ?? ''),
42	    tc: fmtFrame(e.frame, fps),
43	  })), [events, fps]);
44	
45	  const visible = useMemo(() =>
46	    enriched.filter(e => e.frame <= currentFrame && matchFilter(e.cat, filter)),
47	    [enriched, currentFrame, filter],
48	  );
49	
50	  useEffect(() => {
51	    if (scrollRef.current) {
52	      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
53	    }
54	  }, [visible.length]);
55	
56	  return (
57	    <div className="glass" style={{ display: 'flex', flexDirection: 'column', height: '100%', overflow: 'hidden' }}>
58	      {/* Header */}
59	      <div style={{ padding: '14px 16px 10px', display: 'flex', flexDirection: 'column', gap: 11, borderBottom: '1px solid var(--border-subtle)', flexShrink: 0 }}>
