3	import type { FighterProfile } from '../../mocks/fightMock';
4	import type { Event } from '../../types/Event';
5	import { derivePaceBuckets } from '../../utils/liveStats';
6	
7	interface MomentumProps {
8	  time: number;
9	  duration: number;
10	  r1EndSeconds: number;
11	  events: Event[];
12	  fps: number;
13	  fighters: { red: FighterProfile; blue: FighterProfile };
14	}
15	
16	export default function Momentum({ time, duration, r1EndSeconds, events, fps, fighters }: MomentumProps) {
17	  const d = duration > 0 ? duration : DURATION;
18	  const r1 = r1EndSeconds > 0 ? r1EndSeconds : R1_END;
